START TRANSACTION;
SELECT gold, bank FROM users WHERE id IN (:a, :b) ORDER BY id FOR UPDATE;
-- check the balances on the locked values, then
UPDATE users SET bank = bank - :amount WHERE id = :a;
UPDATE users SET bank = bank + :amount WHERE id = :b;
COMMIT;

-- or: accept only if exactly one row changed
UPDATE users SET gold = gold - :amount WHERE id = :a AND gold >= :amount;
